. /tmp/claude-0/-home-user/37d8642d-fcb5-5f5b-86e8-f46de44d221c/scratchpad/verify-db/ctx.sh
echo "-- T4 setup: resolvePostgresAccess support branch (beginSubject only: subject_id, no department/support settings)"
{ echo "begin; set local role authenticated; select set_config('tracepoint.subject_id','$PA',true) is not null;"; echo "select public.is_platform_admin() as allowed;"; echo "select id,name from public.platform_support_context('$DA');"; echo "commit;"; } | RT 2>&1
echo "-- T4 PATCH reads (support-mode data client: subject+department+support_department_id)"
tx $PA $DA $DA "select id from public.departments t where t.id='$DA'; select code,is_active from public.feature_catalog t where t.code='equipment_readiness'; select is_enabled from public.department_features t where t.department_id='$DA' and t.feature_code='equipment_readiness'; select tracepoint_auth.is_platform_supporting('$DA') supporting, has_department_permission('$DA','administer_department') admin_perm;" | RT 2>&1
echo "-- T4 PATCH write: department_features upsert (as generated by PostgresDataClient upsert)"
tx $PA $DA $DA "insert into public.department_features(department_id,feature_code,is_enabled,enabled_at,disabled_at,updated_at,updated_by) values ('$DA','equipment_readiness',false,null,now(),now(),'$PA') on conflict(department_id,feature_code) do update set is_enabled=excluded.is_enabled,enabled_at=excluded.enabled_at,disabled_at=excluded.disabled_at,updated_at=excluded.updated_at,updated_by=excluded.updated_by;" | RT 2>&1
echo "-- T4 PATCH write 2: department_feature_events insert"
tx $PA $DA $DA "insert into public.department_feature_events(department_id,feature_code,previous_enabled,new_enabled,actor_user_id,reason) values ('$DA','equipment_readiness',true,false,'$PA','test');" | RT 2>&1
echo "-- T4 set_platform_entitlement in support mode for Dept A"
tx $PA $DA $DA "select public.set_platform_entitlement('$DA','equipment_readiness',false,'support-mode test');" | RT 2>&1
echo "-- T4 set_platform_entitlement targeting Dept B while supporting Dept A"
tx $PA $DA $DA "select public.set_platform_entitlement('$DB','firearms',false,'cross-dept test');" | RT 2>&1
echo "-- T4 negative: dept admin A (not platform admin) calls set_platform_entitlement"
tx $ADMA $DA "" "select public.set_platform_entitlement('$DA','firearms',false,'x');" | RT 2>&1
echo "-- T4 negative: platform admin with support_department_id but connected as superuser session (session_user<>tracepoint_runtime)"
{ tx $PA $DA $DA "select tracepoint_auth.is_platform_supporting('$DA') supporting_when_session_user_postgres;"; } | SU 2>&1
SU -c "select department_id,feature_code,is_enabled,updated_by from department_features order by 1,2" -c "select department_id,feature_code,previous_enabled,new_enabled,actor_user_id,reason from department_feature_events" 2>&1
echo "-- T7 EQP-09: lifecycle_status='out_of_service' as equipment manager (app RLS context)"
tx $EQM $DA "" "update public.equipment_assets t set lifecycle_status='out_of_service' where t.department_id='$DA' and t.id='ea000000-0000-4000-8000-000000000001' returning id,lifecycle_status;" | RT 2>&1
echo "-- T7 as superuser (no RLS) to isolate the CHECK constraint"
SU -c "update equipment_assets set lifecycle_status='out_of_service' where id='ea000000-0000-4000-8000-000000000001'" -c "select pg_get_constraintdef(oid) from pg_constraint where conname='equipment_assets_lifecycle_status_check'" 2>&1
